/* JS Learning · CISA Certification Hub
   Module is loaded on demand by index.html. Curriculum and question banks live in separate JSON files.
   All user work is saved through the parent application's existing authenticated Firebase progress document.
*/
let root, readParent, writeParent, syllabus, templates={}, state, tab='overview', weekIndex=0, focusedTopic=null, editTopic=null;
let examBank=null, examPage=0, reviewQuestion=0, timer=null, stopWatch=null, stopwatchStart=null, stopwatchElapsed=0;
const bankCache={};
let qIndex=null, mxSession=null, mxFilter='all', modals=[], modalAnim=null, ctx={isAdmin:false,verifyAdmin:null}, adminErr='', adminBusy=false, adminEmail='', qzSession=null, focus={dur:25,left:1500,running:false,endAt:0,domain:'1',topic:''}, focusTimer=null;
const locked=()=>!!(state&&state.planLock&&state.planLock.locked);
const LOCKED_ACTIONS=['mode-normal','mode-relaxed','plan-config','edit-topic','new-topic','move-up','move-down','delete-custom','reset-plan','catchup'];
function modeButtons(sz){const L=locked(),cur=state.planMode;return [['normal','Normal'],['relaxed','Relaxed']].map(([m,l])=>{if(!L)return button('mode-'+m,l,(cur===m?'primary ':'')+sz);return cur===m?`<span class="cisa-btn primary ${sz} pl-static" aria-current="true">🔒 ${l}</span>`:`<button type="button" class="cisa-btn ${sz} pl-off" disabled aria-disabled="true" title="Plan is locked">${l}</button>`}).join('')}
const MX_INTERVALS=[1,3,7,14], MX_MASTERY=2;
const WD=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
const $=(sel)=>root?.querySelector(sel);
const $$=(sel)=>[...(root?.querySelectorAll(sel)||[])];
const h=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const fmtDate=ds=>ds?new Date(ds+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'—';
const asDate=s=>new Date(s+'T12:00:00');
const dateStr=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
const dateAdd=(s,n)=>{const d=asDate(s);d.setDate(d.getDate()+n);return dateStr(d)};
const dayDiff=(a,b)=>Math.round((asDate(b)-asDate(a))/86400000);
const dayIdx=d=>(asDate(d).getDay()+6)%7;
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const pct=(a,b)=>b?Math.round(a/b*100):0;
const pad=n=>String(n).padStart(2,'0');
const simple=xs=>xs.filter(Boolean).join(' · ');
function defaultState(){return {planMode:'normal',plans:{},complete:{},topicEdits:{},order:[],customTasks:[],hidden:[],logs:[],notes:{},revisions:{},results:[],drafts:{},activeMock:null,registration:{registered:false,booked:false},revisionCounts:{},mistakes:{},mockAttempts:{},updatedAt:Date.now()};}
/* ---- answer-order shuffling: one 4-digit permutation per question, stored as a compact string ---- */
function makeOrder(n){let s='';for(let i=0;i<n;i++){const p=[0,1,2,3];for(let j=3;j>0;j--){const k=Math.floor(Math.random()*(j+1));[p[j],p[k]]=[p[k],p[j]]}s+=p.join('')}return s}
function permAt(order,i){if(!order||order.length<(i+1)*4)return [0,1,2,3];return [...order.slice(i*4,i*4+4)].map(Number)}
/* ---- first attempts vs retakes ---- */
function normaliseAttempts(){const counts={};for(const r of state.results){if(!r.attempt){counts[r.mockId]=(counts[r.mockId]||0)+1;r.attempt=counts[r.mockId]}else counts[r.mockId]=Math.max(counts[r.mockId]||0,r.attempt)}for(const [k,v] of Object.entries(counts))state.mockAttempts[k]=Math.max(state.mockAttempts[k]||0,v)}
function firstResults(){return state.results.filter(r=>r.attempt===1)}
function firstResult(id){return state.results.find(r=>r.mockId===id&&r.attempt===1)}
function readiness(){const scores=domainScore().filter(d=>d.mockQuestions>0);if(!scores.length)return null;const w=scores.reduce((n,d)=>n+d.weight,0);return {percent:Math.round(scores.reduce((n,d)=>n+d.weight*d.mockAccuracy,0)/w),questions:scores.reduce((n,d)=>n+d.mockQuestions,0),domains:scores.length}}
function trimResults(list){if(list.length<=30)return list;const firsts=list.filter(r=>r.attempt===1),rest=list.filter(r=>r.attempt!==1);return [...firsts,...rest.slice(-(30-firsts.length))].sort((a,b)=>a.date.localeCompare(b.date))}
/* ---- mistakes notebook (spaced review) ---- */
const today=()=>dateStr(new Date());
function mxList(){return Object.entries(state.mistakes).map(([id,v])=>({id,...v}))}
function mxDue(){const t=today();return mxList().filter(x=>!x.x&&x.d<=t)}
function mxActive(){return mxList().filter(x=>!x.x)}
function mxAddWrong(id,mockId){const t=today(),cur=state.mistakes[id];state.mistakes[id]=cur?{...cur,d:dateAdd(t,1),s:0,x:false,w:(cur.w||1)+1}:{m:mockId,a:t,d:dateAdd(t,1),n:0,s:0,w:1}}
function mxRecord(id,correct){const c=state.mistakes[id];if(!c)return;const t=today();c.l=t;if(correct){c.n=(c.n||0)+1;c.s=(c.s||0)+1;if(c.s>=MX_MASTERY){c.x=true;c.d=t}else c.d=dateAdd(t,MX_INTERVALS[Math.min(c.n,MX_INTERVALS.length-1)])}else{c.s=0;c.w=(c.w||1)+1;c.d=dateAdd(t,MX_INTERVALS[0])}}
async function loadAllBanks(){await Promise.all([1,2,3].map(id=>loadBank(id,false)));if(!qIndex){qIndex=new Map();for(const id of [1,2,3])for(const q of bankCache[id].questions)qIndex.set(q.id,{...q,mockId:id})}return qIndex}
function persist(){state.updatedAt=Date.now();writeParent(state);}
async function fetchData(file){const r=await fetch(new URL(file,import.meta.url),{cache:'no-store'});if(!r.ok)throw Error('Unable to load '+file+' ('+r.status+'). Upload the entire cisa/ directory.');return r.json()}
function allOfficial(){return syllabus.domains.flatMap(d=>d.topics)}
function allTopics(){const base=allOfficial(),custom=state.customTasks||[];const ids=state.order||[];const position=new Map(ids.map((id,i)=>[id,i]));return base.concat(custom).sort((a,b)=>(position.get(a.id)??9999)-(position.get(b.id)??9999))}
function titleOf(t){return state.topicEdits?.[t.id]?.title||t.title}
function minsOf(t){return clamp(Number(state.topicEdits?.[t.id]?.minutes??t.minutes??70)||70,15,300)}
function noteOf(t){return state.topicEdits?.[t.id]?.notes||''}
function includedTopics(){return allTopics().filter(t=>!state.hidden.includes(t.id))}
function getPlan(){return state.plans[state.planMode]||templates[state.planMode]}
function ensureState(){state=Object.assign(defaultState(),readParent()||{});state.plans=state.plans||{};state.complete=state.complete||{};state.topicEdits=state.topicEdits||{};state.order=state.order||[];state.customTasks=state.customTasks||[];state.hidden=state.hidden||[];state.logs=state.logs||[];state.notes=state.notes||{};state.revisions=state.revisions||{};state.results=state.results||[];state.drafts=state.drafts||{};state.registration=state.registration||{registered:false,booked:false};state.revisionCounts=state.revisionCounts||{};state.mistakes=state.mistakes||{};state.mockAttempts=state.mockAttempts||{};normaliseAttempts(); if(!state.plans.normal)state.plans.normal=structuredClone(templates.normal);if(!state.plans.relaxed)state.plans.relaxed=structuredClone(templates.relaxed);if(!templates[state.planMode])state.planMode='normal';if(state.planLock&&state.planLock.locked&&templates[state.planLock.mode])state.planMode=state.planLock.mode;}
function totalComplete(){const done=allOfficial().filter(t=>state.complete[t.id]);return {done:done.length,total:allOfficial().length,percent:pct(done.length,allOfficial().length)}}
function timeline(){const p=getPlan(),result=[],byday={},tasks=includedTopics(),review=Math.max(3,Number(p.reviewDays)||10);if(!p.start||!p.examDate||dayDiff(p.start,p.examDate)<3)return {byday,days:[],warning:'Study start must be at least three days before the target exam date.'};
 const studyEnd=dateAdd(p.examDate,-review); const capacity={}, dates=[];
 for(let ds=p.start; ds<=studyEnd && dates.length<730;ds=dateAdd(ds,1)){
   const min=clamp(Number((p.weeklyMinutes||[])[dayIdx(ds)])||0,0,600);if(min>0){capacity[ds]=min;dates.push(ds)}
 }
 let cursor=0,overflow=0;
 for(const t of tasks){let left=minsOf(t),part=0,override=(state.topicEdits[t.id]||{}).date; if(override){(byday[override]??=[]).push({topic:t,minutes:left,customDate:true,part:1});continue}
  while(left>0){if(cursor>=dates.length){overflow+=left;break} const ds=dates[cursor],used=Math.min(left,capacity[ds]); if(used>0){(byday[ds]??=[]).push({topic:t,minutes:used,part:++part});left-=used;capacity[ds]-=used}if(capacity[ds]<1)cursor++}
 }
 // Exams are deliberately in the final revision period. Mock bookings are suggestions, not PSI appointments.
 for(const [id,offset] of [[1,review-1],[2,Math.max(4,Math.floor(review/2))],[3,2]]){const ds=dateAdd(p.examDate,-offset);(byday[ds]??=[]).push({mock:id,minutes:240})}
 (byday[p.examDate]??=[]).push({exam:true,minutes:240});
 const days=Object.keys(byday).sort();let warning='';if(overflow)warning=`Your study schedule is short by ${Math.ceil(overflow/60)} hours. Increase study minutes, extend dates, or reduce optional tasks.`;if(tasks.length<60)warning+=(warning?' ':'')+'Some official syllabus topics are excluded; coverage will be incomplete.';
 return {byday,days,warning,overflow,studyEnd};}
function domainScore(){const data=syllabus.domains.map(d=>({domain:d.id,weight:d.weight,name:d.name,questions:0,correct:0,mockQuestions:0,mockCorrect:0,completed:d.topics.filter(t=>state.complete[t.id]).length,total:d.topics.length,confidence:[]}));const byId=new Map(data.map(d=>[d.domain,d]));for(const r of firstResults()){const latest=r.stats||{};for(const [k,v] of Object.entries(latest)){const d=byId.get(Number(k));if(d){d.questions+=Number(v.total)||0;d.correct+=Number(v.correct)||0;d.mockQuestions+=Number(v.total)||0;d.mockCorrect+=Number(v.correct)||0}}}for(const log of state.logs){const d=byId.get(Number(log.domain));if(d&&Number(log.questions)>0){d.questions+=Number(log.questions);d.correct+=Number(log.correct)||0}if(d&&Number(log.confidence)>0)d.confidence.push(+log.confidence)}return data.map(d=>({...d,accuracy:d.questions?pct(d.correct,d.questions):null,mockAccuracy:d.mockQuestions?d.mockCorrect/d.mockQuestions*100:null,coverage:pct(d.completed,d.total),confidence:d.confidence.length?+(d.confidence.reduce((a,b)=>a+b,0)/d.confidence.length).toFixed(1):null}))}
function weakTopics(){const m=new Map();for(const r of firstResults()){const entries=r.topicStats||{};for(const [id,v] of Object.entries(entries)){const old=m.get(id)||{correct:0,total:0};old.correct+=v.correct;old.total+=v.total;m.set(id,old)}}for(const log of state.logs){if(!log.topicId||!+log.questions)continue;const old=m.get(log.topicId)||{correct:0,total:0};old.correct+=Number(log.correct)||0;old.total+=Number(log.questions)||0;m.set(log.topicId,old)}return allTopics().map(t=>{const a=m.get(t.id)||{correct:0,total:0},accuracy=a.total?pct(a.correct,a.total):null,weight=syllabus.domains.find(d=>d.id===t.domain)?.weight||10;const points=a.total?clamp(80-accuracy,0,80)*(Math.min(a.total,20)/20):0;const priority=points+weight*.45+(!state.complete[t.id]?16:0);return {topic:t,correct:a.correct,total:a.total,accuracy,priority,done:!!state.complete[t.id]}}).sort((a,b)=>b.priority-a.priority)}
function button(act,label,kind='',extra=''){return `<button type="button" class="cisa-btn ${kind}" data-action="${act}" ${extra}>${label}</button>`}
function badge(text,type=''){return `<span class="cisa-badge ${type}">${h(text)}</span>`}
function progress(value){return `<span class="cisa-progress"><i style="width:${clamp(value,0,100)}%"></i></span>`}
function kpi(label,value,sub){return `<div class="cisa-kpi"><span>${h(label)}</span><strong>${h(value)}</strong><small>${h(sub)}</small></div>`}
function header(){const p=getPlan(),dl=Math.max(0,dayDiff(dateStr(new Date()),p.examDate));return `<section class="view-head cisa-head ed-titlebar"><div><span class="eyebrow">CISA certification</span><h2>CISA Study Hub</h2></div><div class="ed-count"><b>${dl} days</b><span>Exam ${h(fmtDate(p.examDate))} · ${h(state.planMode==='normal'?'Normal':'Relaxed')} plan</span><div class="d3-planbtns">${modeButtons('sm')}</div></div></section><div class="cisa-tabs" role="navigation" aria-label="CISA sections">${[['overview','Overview'],['planner','Study planner'],['syllabus','Course & syllabus'],['recorder','Daily recorder'],['revision','Revision'],['mocks','Mock exams'],['mistakes',`Mistakes${mxDue().length?` <span class="cisa-count">${mxDue().length}</span>`:''}`],['analytics','Analytics'],['notes','Notes & backup']].map(([k,v])=>`<button type="button" data-action="nav" data-target="${k}" aria-current="${tab===k}">${v}</button>`).join('')}</div>`}
function overview(){const c=totalComplete(),scores=domainScore(),p=getPlan(),t=timeline(),now=dateStr(new Date()),mins=state.logs.reduce((n,l)=>n+(Number(l.minutes)||0),0),rd=readiness(),due=mxDue().length;
 const items=t.days.filter(d=>d>=now).flatMap(d=>t.byday[d].map(x=>({d,x}))),task=items.find(o=>o.x.topic&&!state.complete[o.x.topic.id])||items[0];
 const label=ds=>ds===now?'Today':ds===dateAdd(now,1)?'Tomorrow':new Date(ds+'T12:00:00').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'});
 const nameOf=x=>x.topic?`${x.topic.id} · ${titleOf(x.topic)}`:x.mock?`Mock exam ${x.mock}`:'CISA examination';
 const coming=items.filter(o=>!(o.x.topic&&state.complete[o.x.topic.id])).slice(1,6);
 return `<section class="ed-card ed-hero"><div><span class="ed-kicker">${task&&task.d===now?'Today’s task':'Next task'}</span>
  <h3 class="ed-title">${task?h(nameOf(task.x)):'Your plan is complete'}</h3>
  <p class="ed-sub">${task?`${h(label(task.d))} · ${task.x.topic?'Domain '+h(task.x.topic.domain)+' · ':''}${task.x.minutes} minutes`:'Every planned topic is done. Use the mocks to check readiness.'}</p>
  <div class="ed-actions">${task&&task.x.topic?button('open-topic','Read topic →','primary',`data-topic="${h(task.x.topic.id)}"`)+button('nav','Log a session','','data-target="recorder"'):button('nav','Mock exams →','primary','data-target="mocks"')}${due?button('mx-start',`Review ${due} mistake${due===1?'':'s'}`):''}</div></div>
  <div class="ed-stats"><div><b>${c.done}/${c.total}</b><span>topics covered</span></div><div><b>${(mins/60).toFixed(1)}h</b><span>hours logged</span></div><div><b>${rd?rd.percent+'%':'—'}</b><span>Readiness · first attempts</span></div><div><b>${due}</b><span>mistakes due</span></div></div></section>
 <h3 class="ed-sect">Readiness by domain <span>studied, weighted like the real exam</span></h3>
 <section class="ed-card ed-list">${scores.map(d=>`<div class="ed-dom"><span class="k">D${d.domain}</span><span class="n">${h(d.name)}<small>${d.weight}% of exam${d.accuracy!==null?' · '+d.accuracy+'% practice accuracy':''}</small></span><span class="d3-bar"><i style="width:${d.coverage}%"></i></span><span class="pc">${d.coverage}%</span></div>`).join('')}</section>
 <h3 class="ed-sect">Coming up <span>${button('nav','Open planner →','sm','data-target="planner"')}</span></h3>
 <section class="ed-card ed-list">${coming.length?coming.map(o=>`<div class="ed-up"><span class="dt">${h(label(o.d))}</span><span class="nm">${h(nameOf(o.x))}</span><span class="mn">${o.x.minutes} min</span></div>`).join(''):'<div class="ed-up"><span class="nm" style="grid-column:1/-1;color:#6B7A90">No upcoming items. Adjust your plan dates in the planner.</span></div>'}</section>
 <p class="d3-fine">Practice results are learning indicators, not an ISACA scaled score. Planner dates are targets; book your exam with ISACA/PSI separately.</p>`}
function weeklyFields(p){return `<div class="cisa-week">${WD.map((d,i)=>`<label>${d}<input name="wd${i}" type="number" min="0" max="600" step="15" value="${+p.weeklyMinutes[i]||0}" aria-label="${d} study minutes"></label>`).join('')}</div>`}
function planner(){const p=getPlan(),t=timeline(),now=dateStr(new Date()),c=totalComplete(),capacity=(p.weeklyMinutes||[]).reduce((n,v)=>n+Number(v||0),0),daysLeft=Math.max(0,dayDiff(now,p.examDate)),total=Math.max(1,dayDiff(p.start,p.examDate)),elapsed=clamp(dayDiff(p.start,now),0,total);
 const next=t.days.filter(d=>d>=now).flatMap(d=>t.byday[d].map(x=>({d,x}))).filter(o=>!(o.x.topic&&state.complete[o.x.topic.id])).slice(0,4);
 const label=ds=>ds===now?'Today':ds===dateAdd(now,1)?'Tomorrow':new Date(ds+'T12:00:00').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'});
 const nameOf=x=>x.topic?`${x.topic.id} · ${titleOf(x.topic)}`:x.mock?`Mock exam ${x.mock}`:'CISA examination';
 return `${locked()?'':`<section class="pl-setup"><div><b>Set up your study plan</b><span>One-time setup: choose Normal or Relaxed, set your dates and weekly hours, then lock it. After locking, only the admin can change the plan.</span></div>${button('plan-config','Set up plan','primary')}</section>`}<section class="ed-card ed-hero pl-hero"><div><span class="ed-kicker">Your study plan</span><h3 class="ed-title">${h(p.title)}</h3>
  <p class="ed-sub">${h(fmtDate(p.start))} → ${h(fmtDate(p.examDate))} · ${Math.round(capacity/60*10)/10} h per week</p>
  <div class="pl-time"><span class="d3-bar"><i style="width:${Math.round(elapsed/total*100)}%"></i></span><div class="pl-time-l"><span>Start</span><span>${daysLeft} days to exam</span><span>Exam</span></div></div>
  <div class="ed-actions">${button('plan-open','View full plan','primary')}${button('plan-ics','Add to calendar')}${locked()?`<span class="pl-lockbadge">🔒 Locked${state.planLock.at?' · '+h(fmtDate(state.planLock.at.slice(0,10))):''}</span>${ctx.isAdmin?button('admin-unlock','Unlock plan','sm'):button('admin-auth','Admin unlock','sm pl-ghost')}`:button('plan-config','Set up plan')}</div></div>
  <div class="ed-stats"><div><b>${c.done}/${c.total}</b><span>topics done</span></div><div><b>${t.days.filter(d=>d>=now&&t.byday[d].some(x=>x.topic)).length}</b><span>study days left</span></div><div><b>${state.planMode==='normal'?'Normal':'Relaxed'}</b><span>plan type</span></div><div><b>${p.reviewDays}</b><span>revision days</span></div></div></section>
 ${t.warning?`<div class="pl-warn">${h(t.warning)}</div>`:''}
 <h3 class="ed-sect" style="margin-top:28px!important">Up next <span>your next study sessions</span></h3>
 <section class="ed-card ed-list">${next.length?next.map(o=>`<div class="ed-up"><span class="dt">${h(label(o.d))}</span><span class="nm">${h(nameOf(o.x))}</span><span class="mn">${o.x.minutes} min</span></div>`).join(''):'<div class="ed-up"><span class="nm" style="grid-column:1/-1;color:#6B7A90">Nothing scheduled. Open Configure to adjust dates or hours.</span></div>'}</section>`}
function planFullUI(){const p=getPlan(),t=timeline(),now=dateStr(new Date()),days=t.days;const overdueMap=new Map();for(const ds of days.filter(d=>d<now)){for(const it of t.byday[ds]){if(it.topic&&!state.complete[it.topic.id])overdueMap.set(it.topic.id,it.topic)}}const overdue=[...overdueMap.values()];
 const weeks=[];let wk=null;for(const ds of days){const w=Math.floor(dayDiff(p.start,ds)/7);if(!wk||wk.n!==w){wk={n:w,days:[]};weeks.push(wk)}wk.days.push(ds)}
 const visible=null;
 return `${t.warning?`<div class="pl-warn">${h(t.warning)}</div>`:''}${overdue.length?`<div class="pl-warn"><strong>${overdue.length} unfinished topics from earlier dates</strong>${overdue.slice(0,5).map(x=>`<div class="cisa-row" style="margin-top:7px"><span>${h(x.id)} · ${h(titleOf(x))}</span>${locked()?'':button('catchup','Move to next study day','sm',`data-topic="${h(x.id)}"`)}</div>`).join('')}</div>`:''}
 ${weeks.map(w=>`<div class="pl-week"><div class="pl-week-h"><b>Week ${w.n+1}</b><span>${h(fmtDate(w.days[0]))} – ${h(fmtDate(w.days[w.days.length-1]))}</span></div>${w.days.map(ds=>`<div class="cisa-day ${ds===now?'today':''}"><div class="cisa-row"><h3>${h(fmtDate(ds))}</h3>${ds===now?badge('Today'):''}</div>${(t.byday[ds]||[]).map(e=>e.topic?`<div class="cisa-task ${state.complete[e.topic.id]?'done':''}"><label class="cisa-check"><input type="checkbox" data-action="complete" data-topic="${h(e.topic.id)}" ${state.complete[e.topic.id]?'checked':''}><span><strong>${h(e.topic.id)} · ${h(titleOf(e.topic))}</strong><small>${e.minutes} min${e.part>1?' · Part '+e.part:''} · ${h(e.topic.section||'Custom')}</small></span></label>${locked()?'':`<div class="cisa-task-actions">${button('edit-topic','Edit','sm',`data-topic="${h(e.topic.id)}"`)}</div>`}</div>`:`<div class="cisa-task"><span style="font-size:13px"><strong>${e.mock?'Practice mock examination '+e.mock:'Target CISA exam'}</strong><small>${e.minutes} min · ${e.mock?'Use mock center':'External appointment required'}</small></span></div>`).join('')}</div>`).join('')}</div>`).join('')}`}
function planConfigUI(){const p=getPlan(),capacity=(p.weeklyMinutes||[]).reduce((n,v)=>n+Number(v||0),0);
 return `<div class="pl-note">This is a one-time setup. When you press <b>Save &amp; lock plan</b>, the plan is fixed and only the admin can unlock it. You can still tick topics as done.</div><section class="pl-sec"><h4>Plan type</h4><div class="cisa-actions">${modeButtons('')}</div></section>
 <section class="pl-sec"><h4>Dates & weekly hours</h4><form data-form="plan" id="cisaPlanForm"><div class="cisa-fields"><label>Study start<input type="date" name="start" required value="${h(p.start)}"></label><label>Target exam date<input type="date" name="examDate" required value="${h(p.examDate)}"></label><label>Deadline<input type="date" name="deadline" required value="${h(p.deadline)}"></label><label>Final revision days<input type="number" name="reviewDays" min="3" max="40" required value="${+p.reviewDays}"></label><label class="cisa-field-wide">Plan name<input name="title" maxlength="90" value="${h(p.title)}"></label></div><div class="cisa-divider"></div><b style="font-size:12px">Daily study budget (minutes; use 0 for a rest day)</b>${weeklyFields(p)}<div class="cisa-actions" style="margin-top:15px"><button class="cisa-btn primary" type="submit">Save &amp; lock plan</button>${button('reset-plan','Restore default plan')}</div></form> <div class="cisa-help" style="margin-top:14px">Total ${Math.round(capacity/60*10)/10} hours per week. Changing dates or daily minutes recalculates unfinished assignments; completed topics, journal entries, results, and custom tasks are preserved.</div></section>
 <section class="pl-sec"><div><div class="cisa-row wrap"><div><h4>Topics & contents</h4><p class="cisa-mini">Rename topics, add personal chapters, change planned dates, adjust duration, reorder tasks or exclude optional work. Official syllabus coverage warns about excluded topics.</p></div>${button('new-topic','+ Add custom topic','primary')}</div>${editTopic?editTopicForm():''}<div class="cisa-table-wrap"><table class="cisa-table"><thead><tr><th>Topic</th><th>Domain</th><th>Time</th><th>Included</th><th>Actions</th></tr></thead><tbody>${allTopics().map((t,i)=>`<tr><td><strong>${h(t.id)} ${h(titleOf(t))}</strong>${noteOf(t)?`<div class="cisa-mini">${h(noteOf(t))}</div>`:''}</td><td>D${h(t.domain||'Custom')}</td><td>${minsOf(t)}m</td><td><label class="cisa-check"><input type="checkbox" data-action="include" data-topic="${h(t.id)}" ${state.hidden.includes(t.id)?'':'checked'}><span>${state.hidden.includes(t.id)?'Excluded':'Yes'}</span></label></td><td><div class="cisa-actions">${button('move-up','↑','sm',`data-topic="${h(t.id)}"`)}${button('move-down','↓','sm',`data-topic="${h(t.id)}"`)}${button('edit-topic','Edit','sm',`data-topic="${h(t.id)}"`)}${t.custom?button('delete-custom','Delete','danger sm',`data-topic="${h(t.id)}"`):''}</div></td></tr>`).join('')}</tbody></table></div></div></section>`}

function editTopicForm(){const t=allTopics().find(t=>t.id===editTopic)||{id:'new',title:'',minutes:60,domain:1,custom:true};const over=state.topicEdits[t.id]||{};const p=getPlan();return `<div class="cisa-edit"><div class="cisa-row"><h3>${editTopic==='new'?'Add personal study item':'Edit '+h(editTopic)}</h3>${button('cancel-edit','Close')}</div><form data-form="topic"><input type="hidden" name="id" value="${h(editTopic)}"><div class="cisa-fields four"><label class="cisa-field-wide">Content or topic title<input name="title" required maxlength="160" value="${h(titleOf(t))}"></label><label>Domain<select name="domain">${[1,2,3,4,5].map(n=>`<option value="${n}" ${t.domain===n?'selected':''}>Domain ${n}</option>`).join('')}</select></label><label>Minutes<input type="number" name="minutes" min="15" max="300" value="${minsOf(t)}"></label><label>Preferred date (optional)<input type="date" name="date" value="${h(over.date||'')}"></label><label class="cisa-field-wide">Your notes and learning objectives<textarea name="notes" maxlength="1500">${h(noteOf(t))}</textarea></label></div><div class="cisa-actions"><button type="submit" class="cisa-btn primary">Save topic changes</button>${button('cancel-edit','Cancel')}</div></form></div>`}
function syllabusUI(){const c=totalComplete();return `<section class="cisa-card cisa-section"><div class="cisa-row wrap"><div><h2>Official CISA topic map</h2><p class="cisa-text cisa-muted">60 published topics across five domains. Each topic has a concise original explanation, audit scenario, likely risk, suggested control and relevant evidence. Supplement these outlines with ISACA's study materials.</p></div>${badge(c.done+' / '+c.total+' completed')}</div>${progress(c.percent)}${focusedTopic?detailUI():''}${syllabus.domains.map(d=>`<div class="cisa-domain"><div class="cisa-row"><h3>Domain ${d.id}: ${h(d.name)}</h3>${badge(d.weight+'% exam weight')}</div>${d.topics.map(t=>`<div class="cisa-task ${state.complete[t.id]?'done':''}"><label class="cisa-check"><input type="checkbox" data-action="complete" data-topic="${h(t.id)}" ${state.complete[t.id]?'checked':''}><span><strong>${h(t.id)} · ${h(titleOf(t))}</strong><small>${h(t.section)} · ${minsOf(t)} minutes${state.hidden.includes(t.id)?' · Excluded from plan':''}</small></span></label><div class="cisa-task-actions">${button('open-topic','Open lesson','sm',`data-topic="${h(t.id)}"`)}</div></div>`).join('')}</div>`).join('')}</section>`}
function detailUI(){const t=allTopics().find(x=>x.id===focusedTopic);if(!t)return '';return `<section class="cisa-highlight" id="cisa-topic-detail"><div class="cisa-row wrap"><div><span class="cisa-overline">Domain ${h(t.domain)} · ${h(t.id)}</span><h2>${h(titleOf(t))}</h2></div>${button('close-topic','Close topic')}</div><p class="cisa-text">${h(t.intro||'Personal learning item. Use the notes and study recorder to capture how this fits your exam plan.')}</p><h3>Practical scenario</h3><p class="cisa-text">${h(t.example||noteOf(t)||'Set a practical learning objective for this study item.')}</p><h3>What the auditor should consider</h3><p class="cisa-text">${h(t.auditApproach||'Document the control objective, evidence, risk and relevant audit criteria.')}</p>${noteOf(t)?`<div class="cisa-help"><b>Personal learning notes:</b> ${h(noteOf(t))}</div>`:''}<div class="cisa-actions">${button('complete-toggle',state.complete[t.id]?'Mark not yet complete':'Mark topic complete','primary',`data-topic="${h(t.id)}"`)}${locked()?'':button('edit-topic','Customize this topic','','data-topic="'+h(t.id)+'"')}</div></section>`}
function recorder(){const today=dateStr(new Date()),sum=state.logs.reduce((n,x)=>n+Number(x.minutes||0),0);return focusCard()+`<div class="cisa-grid two cisa-section"><section class="cisa-card"><h2>Record a study session</h2><p class="cisa-text cisa-muted">Track actual learning, not just checkboxes. Use practice results and confidence to build targeted revision.</p><form data-form="log"><div class="cisa-fields"><label>Date<input type="date" name="date" value="${h(today)}" required></label><label>Duration (minutes)<input type="number" min="1" max="1440" name="minutes" required value="60" id="cisa-duration"></label><label>Domain<select name="domain">${syllabus.domains.map(d=>`<option value="${d.id}">D${d.id} · ${h(d.name)}</option>`).join('')}</select></label><label class="cisa-field-wide">Topic<select name="topicId"><option value="">General study / multiple topics</option>${allTopics().map(t=>`<option value="${h(t.id)}">${h(t.id)} · ${h(titleOf(t))}</option>`).join('')}</select></label><label>Questions attempted<input type="number" name="questions" min="0" max="1000" value="0"></label><label>Correct answers<input type="number" name="correct" min="0" max="1000" value="0"></label><label>Confidence (1–5)<select name="confidence">${[1,2,3,4,5].map(n=>`<option value="${n}" ${n===3?'selected':''}>${n} / 5</option>`).join('')}</select></label><label class="cisa-field-wide">Learning notes / questions to revisit<textarea name="notes" maxlength="1000" placeholder="What did you learn? Which concepts are unclear?"></textarea></label></div><div class="cisa-actions" style="margin-top:15px"><button type="submit" class="cisa-btn primary">Save study record</button>${button('timer-start','Start timer')}${button('timer-stop','Stop timer') }<span class="cisa-timer" id="cisa-study-timer">00:00</span></div></form></section><section class="cisa-card"><h2>Session history</h2><p class="cisa-mini">${state.logs.length} sessions · ${(sum/60).toFixed(1)} hours logged</p><div class="cisa-scroll">${state.logs.length?[...state.logs].reverse().map(l=>`<div class="cisa-list-item"><div class="cisa-row"><strong>${h(fmtDate(l.date))}</strong>${badge(l.minutes+' min')}</div><div class="cisa-mini">D${h(l.domain)} ${h(l.topicId||'Mixed topics')} · ${l.questions?`${l.correct}/${l.questions} questions correct`:'Reading session'} · Confidence ${h(l.confidence)}/5</div>${l.notes?`<p class="cisa-text" style="margin:8px 0 0">${h(l.notes)}</p>`:''}<div class="cisa-actions">${button('delete-log','Delete','danger sm',`data-id="${h(l.id)}"`)}</div></div>`).join(''):'<div class="cisa-empty">No study sessions recorded yet.</div>'}</div></section></div>`}
function revisionsUI(){const rank=weakTopics(),scores=domainScore();const tracked=rank.filter(x=>x.total>0),incomplete=rank.filter(x=>!x.done),top=tracked.filter(x=>x.accuracy<80).slice(0,12);return `<div class="cisa-section cisa-grid two"><section class="cisa-card"><h2>Focus first: weakest domains</h2>${[...scores].sort((a,b)=>((a.accuracy??50)-(b.accuracy??50))||b.weight-a.weight).map(d=>`<div class="cisa-domain"><div class="cisa-row"><strong>D${d.domain} · ${h(d.name)}</strong>${badge(d.accuracy===null?'No data':d.accuracy+'%',d.accuracy!==null&&d.accuracy<75?'warn':'')}</div>${progress(d.accuracy??0)}<span class="cisa-mini">${d.questions} practice questions · ${d.coverage}% syllabus covered · ${d.weight}% exam weight</span></div>`).join('')}<div class="cisa-help">Priorities reflect practice accuracy, study coverage and exam weight. Small samples are treated cautiously; this is not a pass prediction.</div></section><section class="cisa-card"><h2>Recommended revision</h2>${(top.length?top:incomplete.slice(0,8)).map(x=>`<div class="cisa-domain"><div class="cisa-row wrap"><strong>${h(x.topic.id)} · ${h(titleOf(x.topic))}</strong>${badge(x.accuracy===null?'Not studied':x.accuracy+'% accuracy',x.accuracy!==null&&x.accuracy<70?'warn':'')}</div><p class="cisa-mini">${x.accuracy===null?'First understand the fundamentals and work through the example.':x.accuracy<60?'High-priority: re-read the topic, write a risk/control/evidence comparison and retry practice questions.':'Review key decision criteria, then practice applied audit scenarios.'}</p><div class="cisa-actions">${button('open-topic','Read chapter','sm',`data-topic="${h(x.topic.id)}"`)}${button('schedule-review','Add revision reminder','sm',`data-topic="${h(x.topic.id)}"`)}</div></div>`).join('')}${!top.length&&!incomplete.length?'<div class="cisa-empty">All topics marked covered. Use the mock exams to identify new revision priorities.</div>':''}</section></div>${focusedTopic?`<section class="cisa-card cisa-section">${detailUI()}</section>`:''}<section class="cisa-card cisa-section"><h2>Spaced revision reminders</h2><p class="cisa-mini">After a review, schedule the next check in 1, 3, 7 or 14 days depending on confidence. You can reschedule individually.</p>${Object.entries(state.revisions).length?Object.entries(state.revisions).sort((a,b)=>a[1].localeCompare(b[1])).map(([id,date])=>`<div class="cisa-task"><div><strong>${h(id)} · ${h(titleOf(allTopics().find(x=>x.id===id)||{title:id}))}</strong><small>Due ${h(fmtDate(date))}</small></div><div class="cisa-task-actions">${button('review-done','Reviewed','sm',`data-topic="${h(id)}"`)}${button('remove-review','Remove','sm',`data-topic="${h(id)}"`)}</div></div>`).join(''):'<div class="cisa-empty">No revisions due. Choose Add revision reminder on a weak topic.</div>'}</section>`}
function mocksUI(){if(qzSession)return qIndex?quizUI():'<div class="cisa-empty cisa-section">Loading questions…</div>';return qzCard()+`<div class="cisa-grid three cisa-section">${[1,2,3].map(id=>{const latest=[...state.results].reverse().find(r=>r.mockId===id),draft=state.drafts[id];return `<section class="cisa-card"><div class="cisa-overline">Mock exam ${pad(id)}</div><h2>${h(['Foundation & Principles','Applied Audit Scenarios','Integrated Exam Readiness'][id-1])}</h2><p class="cisa-text cisa-muted">150 questions · 240 minutes · four choices · one best answer · 18 / 18 / 12 / 26 / 26 weighting.</p>${(()=>{const fr=firstResult(id);if(!latest)return '<span class="cisa-badge">Not completed</span>';return `<div class="cisa-actions">${fr?badge('First attempt '+pct(fr.correct,fr.total)+'%','good'):''}${latest.attempt>1?badge('Latest retake '+pct(latest.correct,latest.total)+'% · review only'):''}</div>`})()}<div class="cisa-actions" style="margin-top:15px">${button('mock-start',draft?'Resume exam':'Start exam','primary',`data-mock="${id}"`)}${latest?button('mock-result','View results','',`data-mock="${id}"`):''}</div></section>`}).join('')}</div><section class="cisa-card cisa-section"><h2>Mock exam rules</h2><p class="cisa-text">The full-length simulator uses a countdown clock, answer navigation, flagged questions, saved draft answers, submission confirmation and post-exam explanations. The practice bank is original and independently written; it is <strong>not</strong> an official, leaked or licensed ISACA question set. Performance percentages do not represent ISACA scaled scores.</p><p class="cisa-text"><strong>Only your first attempt at each mock counts toward readiness.</strong> Retakes are useful for review, but you have already seen the questions, so their scores mostly measure memory. Answer options are shuffled on every attempt, and every question you miss goes into your Mistakes notebook.</p><p class="cisa-text">For licensed official materials, see <a href="https://www.isaca.org/credentialing/cisa/cisa-practice-quiz" target="_blank" rel="noopener noreferrer">ISACA's practice quiz</a> and <a href="https://www.isaca.org/credentialing/cisa" target="_blank" rel="noopener noreferrer">CISA certification resources</a>.</p></section>`}
function examUI(){if(!examBank)return '<div class="cisa-empty">Loading the mock exam…</div>';const draft=state.drafts[examBank.id];if(!draft)return mocksUI();if(Date.now()>=draft.endAt){finishMock(examBank.id,true);tab='result';return resultUI(examBank.id)};const q=examBank.questions[examPage],answer=draft.answers[q.id],isFlag=draft.flags.includes(q.id),answered=Object.keys(draft.answers).length;return `<div class="cisa-exam"><div class="cisa-row wrap" style="margin-bottom:15px"><div><div class="cisa-overline">Practice exam ${examBank.id}</div><h2>${h(examBank.title)}</h2><div class="cisa-mini">Question ${examPage+1} / 150 · ${answered} answered · ${draft.flags.length} flagged</div></div><div class="cisa-actions"><span class="cisa-timer" data-time>${h(timeLeft(draft.endAt))}</span>${button('mock-submit','Submit exam','danger')}</div></div>${progress(pct(answered,150))}<div class="cisa-grid two cisa-section"><section class="cisa-card"><div class="cisa-row wrap"><span class="cisa-overline">Domain ${q.domain} · Topic ${h(q.topicId)}</span>${badge(q.level)}</div><p class="cisa-text" style="font-size:16px;font-weight:700;margin-top:14px">${h(q.question)}</p><div class="cisa-answers">${permAt(draft.order,examPage).map((o,pos)=>`<button type="button" class="cisa-answer ${answer===o?'selected':''}" data-action="choose" data-option="${o}" aria-pressed="${answer===o}"><b>${'ABCD'[pos]}</b><span>${h(q.choices[o])}</span></button>`).join('')}</div><div class="cisa-actions">${button('mock-prev','← Previous','',''+(examPage===0?'disabled':''))}${button('flag',isFlag?'Unflag question':'Flag for review')}${button('mock-next','Next →','primary',examPage===149?'disabled':'')}</div></section><section class="cisa-card"><h3>Question navigator</h3><p class="cisa-mini">Filled: answered · gold outline: flagged</p><div class="cisa-number-grid">${examBank.questions.map((x,i)=>`<button type="button" data-action="mock-go" data-q="${i}" class="${i===examPage?'current':''} ${draft.answers[x.id]!==undefined?'answered':''} ${draft.flags.includes(x.id)?'flagged':''}" aria-label="Question ${i+1}">${i+1}</button>`).join('')}</div></section></div><div class="cisa-help">This is an exam simulation. Your draft and deadline are retained if you leave and return. Explanations appear only after submission.</div></div>`}
function timeLeft(end){const n=Math.max(0,Math.ceil((end-Date.now())/1000));return `${pad(Math.floor(n/3600))}:${pad(Math.floor(n%3600/60))}:${pad(n%60)}`}
function latestResult(id){return [...state.results].reverse().find(r=>r.mockId===id)}
function resultUI(id){const r=latestResult(id);if(!r)return mocksUI();const q=examBank?.id===id?examBank.questions:[],stats=r.stats||{},first=r.attempt===1,fr=firstResult(id);return `<div class="cisa-section"><section class="cisa-card"><div class="cisa-row wrap"><div><div class="cisa-overline">Practice exam ${id} · ${first?'first attempt':'retake '+(r.attempt-1)}</div><h2>${r.correct} / ${r.total} correct · ${pct(r.correct,r.total)}%</h2><p class="cisa-mini">Submitted ${h(fmtDate(r.date.slice(0,10)))} · ${Math.round(r.elapsed/60000)} minutes used · ${r.unanswered} unanswered</p></div><div class="cisa-actions">${badge(first?'Counts toward readiness':'Review only · not counted',first?'good':'')}${button('nav','Back to mocks','','data-target="mocks"')}</div></div>${first?'':`<div class="cisa-help" style="margin-top:14px">You have seen these questions before, so this score mostly measures recall. Your readiness uses your first attempt${fr?` (${pct(fr.correct,fr.total)}%)`:''}.</div>`}<div class="cisa-grid" style="margin-top:15px">${Object.entries(stats).map(([d,s])=>kpi('Domain '+d,`${pct(s.correct,s.total)}%`,`${s.correct}/${s.total} correct`)).join('')}</div>${(r.wrong||[]).filter(w=>r.answers[w.id]!==undefined).length?`<div class="cisa-callout cisa-row wrap" style="margin-top:15px"><span><b>${(r.wrong||[]).filter(w=>r.answers[w.id]!==undefined).length} questions you answered incorrectly were added to your Mistakes notebook.</b> They come back for review starting tomorrow.</span>${button('nav','Open Mistakes notebook →','sm primary','data-target="mistakes"')}</div>`:''}<div class="cisa-help" style="margin-top:15px">This is a learning percentage. ISACA reports a scaled score (200–800, pass at 450), so this is not an official pass/fail result.</div></section><section class="cisa-card cisa-section"><div class="cisa-row"><h2>Review questions & explanations</h2>${button('mock-reset','Retake this mock','','data-mock="'+id+'"')}</div>${q.length?`${(()=>{const qq=q[reviewQuestion],stale=(r.v||1)<(examBank.version||1)&&(examBank.rewrittenInV2||[]).includes(qq.id),picked=stale?undefined:r.answers[qq.id],perm=permAt(r.order,reviewQuestion);return `<div class="cisa-row"><span class="cisa-mini">Question ${reviewQuestion+1} / 150 · ${h(qq.topicId)}</span>${stale?badge('Rewritten'):badge(picked===qq.answer?'Correct':picked===undefined?'Unanswered':'Review',picked===qq.answer?'good':'warn')}</div>${stale?'<div class="cisa-help" style="margin-top:10px">This question\'s answer options were rewritten after your attempt, so your original choice is not shown. Your score for that attempt is unchanged.</div>':''}<p class="cisa-text cisa-question">${h(qq.question)}</p><div class="cisa-answers">${perm.map((o,pos)=>`<div class="cisa-answer ${o===qq.answer?'is-correct':''} ${o===picked&&o!==qq.answer?'is-wrong':''}"><b>${'ABCD'[pos]}</b><div>${h(qq.choices[o])}${o===qq.answer?' <em>· Best answer</em>':''}${o===picked&&o!==qq.answer?' <em>· Your answer</em>':''}</div></div>`).join('')}</div><div class="cisa-rationale"><b>Why this answer is best</b>${h(qq.explanation)}</div>${picked!==undefined&&picked!==qq.answer&&qq.choiceExplanations?.[picked]?`<div class="cisa-rationale"><b>Why your answer is not best</b>${h(qq.choiceExplanations[picked].replace(/^Not the best answer\.\s*/,''))}</div>`:''}<div class="cisa-actions" style="margin-top:14px">${button('result-prev','← Previous','',''+(reviewQuestion===0?'disabled':''))}${button('result-next','Next →','primary',reviewQuestion===149?'disabled':'')}</div>`})()}`:'<div class="cisa-empty">Loading the separate answer bank for detailed review…</div>'}</section></div>`}
function qSummary(q){const m=q.question.match(/(?:learns that|show that|following condition:)\s*(.*)$/);if(!m)return q.question;const t=m[1];return t.charAt(0).toUpperCase()+t.slice(1)}
function mxStatus(c){const t=today();if(c.x)return badge('Mastered','good');if(c.d<=t)return badge('Due now','warn');const n=dayDiff(t,c.d);return badge(n===1?'Tomorrow':'In '+n+' days')}
function mxSessionUI(){const S=mxSession,total=S.queue.length;if(S.pos>=total){const mastered=S.queue.filter(id=>state.mistakes[id]?.x).length,next=mxActive().map(x=>x.d).sort()[0];return `<section class="cisa-card cisa-section"><div class="cisa-overline">Review complete</div><h2>${S.right} of ${total} correct</h2>${progress(pct(S.right,total))}<p class="cisa-text">${mastered?`${mastered} question${mastered===1?'':'s'} mastered and retired from the notebook. `:''}${S.right<total?'The ones you missed come back tomorrow. ':''}${next?`Your next review is ${h(fmtDate(next))}.`:'Your notebook is clear.'}</p><div class="cisa-actions">${button('mx-end','Back to notebook','primary')}</div></section>`}
 const q=qIndex.get(S.queue[S.pos]),c=state.mistakes[q.id],perm=S.orders[S.pos],picked=S.picked,ans=picked!==null;
 let after='';if(ans){const ok=picked===q.answer;after=`<div class="cisa-rationale"><b>${ok?'Correct.':'Not quite.'} Why the best answer is best</b>${h(q.explanation)}</div>${!ok&&q.choiceExplanations?.[picked]?`<div class="cisa-rationale"><b>Why your answer is not best</b>${h(q.choiceExplanations[picked].replace(/^Not the best answer\.\s*/,''))}</div>`:''}<div class="cisa-help" style="margin-top:12px">${c?.x?'<b>Mastered.</b> You answered this correctly twice in a row, so it leaves the review queue.':ok?`<b>Next review ${h(fmtDate(c.d))}.</b> Answer it correctly once more to master it.`:'<b>Back tomorrow.</b> Spacing resets when you miss a question.'}</div><div class="cisa-actions" style="margin-top:14px">${button('mx-next',S.pos+1<total?'Next question →':'Finish review','primary')}</div>`}
 return `<section class="cisa-card cisa-section"><div class="cisa-row wrap"><div><div class="cisa-overline">Mistakes review · question ${S.pos+1} of ${total}</div><div class="cisa-mini">Mock ${q.mockId} · Domain ${q.domain} · Topic ${h(q.topicId)} · missed ${c?.w||1}×</div></div>${button('mx-end','End session','sm')}</div>${progress(pct(S.pos+(ans?1:0),total))}<p class="cisa-text cisa-question">${h(q.question)}</p><div class="cisa-answers">${perm.map((o,pos)=>ans?`<div class="cisa-answer ${o===q.answer?'is-correct':''} ${o===picked&&o!==q.answer?'is-wrong':''}"><b>${'ABCD'[pos]}</b><div>${h(q.choices[o])}${o===q.answer?' <em>· Best answer</em>':''}${o===picked&&o!==q.answer?' <em>· Your answer</em>':''}</div></div>`:`<button type="button" class="cisa-answer" data-action="mx-pick" data-option="${o}"><b>${'ABCD'[pos]}</b><span>${h(q.choices[o])}</span></button>`).join('')}</div>${after}</section>`}
function mistakesUI(){if(!qIndex){loadAllBanks().then(()=>{if(tab==='mistakes')layout()}).catch(e=>fail(e.message));return '<div class="cisa-empty cisa-section">Loading your mistakes…</div>'}
 if(mxSession)return mxSessionUI();
 const all=mxList().filter(c=>qIndex.has(c.id)),active=all.filter(c=>!c.x),mastered=all.filter(c=>c.x),due=mxDue().filter(c=>qIndex.has(c.id));
 const byDomain={};for(const c of active){const d=qIndex.get(c.id).domain;byDomain[d]=(byDomain[d]||0)+1}const top=Object.entries(byDomain).sort((a,b)=>b[1]-a[1])[0];
 const shown=active.filter(c=>mxFilter==='all'||String(qIndex.get(c.id).domain)===mxFilter).sort((a,b)=>a.d.localeCompare(b.d)||(b.w||1)-(a.w||1));
 const row=c=>{const q=qIndex.get(c.id);return `<tr><td><div class="cisa-clamp">${h(qSummary(q))}</div><div class="cisa-mini">Mock ${q.mockId} · ${h(q.id)} · Topic ${h(q.topicId)}</div></td><td>D${q.domain}</td><td>${c.w||1}×</td><td>${c.x?'—':h(fmtDate(c.d))}</td><td>${mxStatus(c)}</td><td><div class="cisa-actions">${c.x?'':button('mx-one','Practise','sm','data-id="'+h(c.id)+'"')}${button('mx-remove','Remove','sm','data-id="'+h(c.id)+'"')}</div></td></tr>`};
 return `<div class="cisa-grid cisa-section">${kpi('Due today',due.length,due.length?'Ready to review now':'Nothing due')}${kpi('In your notebook',active.length,'Still being learned')}${kpi('Mastered',mastered.length,'Correct twice in a row')}${kpi('Most-missed domain',top?'D'+top[0]:'—',top?`${top[1]} open question${top[1]===1?'':'s'}`:'No data yet')}</div>
 <section class="cisa-card cisa-section"><div class="cisa-row wrap"><div><h2>Mistakes notebook</h2><p class="cisa-text cisa-muted">Every mock question you miss lands here. Each one comes back after 1 day, then 3, 7 and 14 days as you get it right, and retires once you answer it correctly twice in a row. Reviews never change your readiness score.</p></div><div class="cisa-actions">${button('mx-start',due.length?`Start review (${due.length} due)`:'Nothing due today','primary',due.length?'':'disabled')}${button('mx-start-all',`Practise all open (${active.length})`,'',active.length?'':'disabled')}</div></div>
 ${all.length?`<div class="cisa-row wrap" style="margin:6px 0 10px"><label class="cisa-inline">Domain <select data-action="mx-filter"><option value="all">All domains</option>${[1,2,3,4,5].map(d=>`<option value="${d}" ${mxFilter===String(d)?'selected':''}>Domain ${d}${byDomain[d]?` (${byDomain[d]})`:''}</option>`).join('')}</select></label><span class="cisa-mini">${shown.length} open question${shown.length===1?'':'s'} shown</span></div><div class="cisa-table-wrap"><table class="cisa-table cisa-mx-table"><thead><tr><th>Question</th><th>Domain</th><th>Missed</th><th>Next review</th><th>Status</th><th></th></tr></thead><tbody>${shown.length?shown.map(row).join(''):'<tr><td colspan="6">No open questions in this domain.</td></tr>'}</tbody></table></div>${mastered.length?`<details class="cisa-details"><summary>${mastered.length} mastered question${mastered.length===1?'':'s'}</summary><div class="cisa-table-wrap"><table class="cisa-table"><tbody>${mastered.map(row).join('')}</tbody></table></div></details>`:''}`:'<div class="cisa-empty">No mistakes yet. Submit a mock exam and every question you miss will appear here for spaced review.</div>'}</section>`}
function mxBegin(ids){mxSession={queue:ids,pos:0,picked:null,right:0,orders:ids.map(()=>{const p=[0,1,2,3];for(let j=3;j>0;j--){const k=Math.floor(Math.random()*(j+1));[p[j],p[k]]=[p[k],p[j]]}return p})};tab='mistakes';layout();window.scrollTo({top:0,behavior:'instant'})}
function analyticsUI(){const scores=domainScore(),t=timeline(),past=state.logs.slice(-14),top=weakTopics().filter(x=>x.accuracy!==null).slice(0,8);return `<div class="cisa-grid">${kpi('Study records',state.logs.length,'Logged sessions')}${kpi('Hours studied',(state.logs.reduce((s,x)=>s+(+x.minutes||0),0)/60).toFixed(1)+'h','Actual time')}${kpi('Topic coverage',totalComplete().percent+'%','Official syllabus')}${kpi('Readiness',readiness()?readiness().percent+'%':'—','First attempts, weighted by domain')}</div><div class="cisa-grid two cisa-section"><section class="cisa-card"><h2>Study time trend</h2><p class="cisa-mini">Minutes per recent recorded session</p>${past.length?`<div class="cisa-chart">${past.map(l=>`<div title="${h(fmtDate(l.date))}: ${+l.minutes} minutes" style="height:${Math.max(6,Math.min(100,(+l.minutes||0)/180*100))}%"></div>`).join('')}</div>`:'<div class="cisa-empty">Log study sessions to see a trend.</div>'}</section><section class="cisa-card"><h2>Coverage and accuracy</h2>${scores.map(d=>`<div class="cisa-domain"><div class="cisa-row"><strong>D${d.domain} · ${h(d.name)}</strong><small>${d.coverage}% coverage · ${d.accuracy??'—'}${d.accuracy!==null?'%':' accuracy'}</small></div>${progress(d.coverage)}</div>`).join('')}</section></div><section class="cisa-card cisa-section"><h2>Practice attempt history</h2><div class="cisa-table-wrap"><table class="cisa-table"><thead><tr><th>Date</th><th>Mock</th><th>Attempt</th><th>Correct</th><th>Percentage</th><th>Time</th></tr></thead><tbody>${state.results.length?state.results.slice().reverse().map(r=>`<tr><td>${h(fmtDate(r.date.slice(0,10)))}</td><td>${r.mockId}</td><td>${r.attempt===1?badge('First · counts','good'):badge('Retake · review')}</td><td>${r.correct}/${r.total}</td><td>${pct(r.correct,r.total)}%</td><td>${Math.round(r.elapsed/60000)}m</td></tr>`).join(''):'<tr><td colspan="6">No submitted mocks yet.</td></tr>'}</tbody></table></div></section>`}
function notesUI(){return `<div class="cisa-grid two cisa-section"><section class="cisa-card"><h2>Personal knowledge notebook</h2><form data-form="notes"><label>Study topic<select name="id" data-action="note-switch">${allTopics().map(t=>`<option value="${h(t.id)}" ${focusedTopic===t.id?'selected':''}>${h(t.id)} · ${h(titleOf(t))}</option>`).join('')}</select></label><label style="margin:13px 0">Your notes<textarea name="note" maxlength="2500" placeholder="Summarize the concept, useful evidence, audit logic, and mistakes to avoid.">${h(state.notes[focusedTopic||allTopics()[0]?.id]||'')}</textarea></label><button class="cisa-btn primary" type="submit">Save note</button></form><div class="cisa-divider"></div>${Object.keys(state.notes).length?Object.entries(state.notes).map(([id,v])=>`<div class="cisa-list-item"><div class="cisa-row"><strong>${h(id)}</strong>${button('note-open','Edit','sm',`data-topic="${h(id)}"`)}</div><p class="cisa-mini">${h(v.slice(0,230))}</p></div>`).join(''):'<div class="cisa-empty">Your personal notes will appear here.</div>'}</section><section class="cisa-card"><h2>Progress export and backup</h2><p class="cisa-text cisa-muted">Your CISA data is stored alongside your authenticated JS Learning account progress through Firebase. You can also export a personal backup and dated study worksheet.</p><div class="cisa-actions">${button('export-json','Export JSON backup','primary')}${button('export-csv','Export study log CSV')}${button('export-plan','Export planner CSV')}</div><div class="cisa-divider"></div><form data-form="import"><label>Restore a previously exported CISA JSON file<input type="file" name="backup" accept=".json,application/json" required></label><button type="submit" class="cisa-btn" style="margin-top:12px">Import backup (replaces CISA records only)</button></form><div class="cisa-divider"></div><h3>Exam registration checklist</h3><label class="cisa-check"><input type="checkbox" data-action="registered" ${state.registration.registered?'checked':''}> Registered and paid through ISACA</label><label class="cisa-check" style="margin-top:10px"><input type="checkbox" data-action="booked" ${state.registration.booked?'checked':''}> Confirmed official PSI exam appointment</label><p class="cisa-mini" style="margin-top:12px">Planner dates are targets, not reservations. Confirm availability and exam eligibility directly with ISACA/PSI.</p></section></div>`}
function adminUI(){return `<form data-form="admin" id="cisaAdminForm" class="pl-sec" autocomplete="off"><p class="cisa-mini" style="margin:0 0 12px">Only the admin account can unlock a locked study plan. The admin's sign-in is checked once and is not kept on this device.</p><div class="cisa-fields" style="grid-template-columns:1fr"><label>Admin email<input type="email" name="email" required autocomplete="off" value="${h(adminEmail)}"></label><label>Admin password<input type="password" name="password" required autocomplete="new-password"></label></div>${adminErr?`<p class="pl-err">${h(adminErr)}</p>`:''}</form>`}
/* ---------- exam-weighted quick quiz ---------- */
const QZ_W={1:.18,2:.18,3:.12,4:.26,5:.26};
function qzCounts(n){const raw=Object.entries(QZ_W).map(([d,w])=>({d:+d,w,x:n*w}));raw.forEach(r=>r.c=Math.floor(r.x));let left=n-raw.reduce((a,r)=>a+r.c,0);[...raw].sort((a,b)=>(b.x-b.c)-(a.x-a.c)||b.w-a.w).slice(0,left).forEach(r=>r.c++);return Object.fromEntries(raw.map(r=>[r.d,r.c]))}
function qzBegin(n){const all=[...qIndex.values()],seen=new Set(state.qzSeen||[]),cnt=qzCounts(n),ids=[];const shuf=a=>{for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
 for(const [d,c] of Object.entries(cnt)){const pool=shuf(all.filter(q=>q.domain===+d));pool.sort((a,b)=>(seen.has(a.id)?1:0)-(seen.has(b.id)?1:0));ids.push(...pool.slice(0,c).map(q=>q.id))}
 shuf(ids);qzSession={queue:ids,pos:0,picked:null,right:0,dom:{},orders:ids.map(()=>shuf([0,1,2,3]))};tab='mocks';layout();window.scrollTo({top:0,behavior:'instant'})}
function qzHistory(){const r=(state.quizzes||[]).slice(-5).reverse();if(!r.length)return '<p class="cisa-mini" style="margin:10px 0 0">No quick quizzes yet.</p>';const avg=Math.round(r.reduce((a,x)=>a+x.right/x.n,0)/r.length*100);return `<div class="qz-hist"><span class="cisa-mini">Last ${r.length}: average <b>${avg}%</b></span>${r.map(x=>`<span class="qz-chip ${x.right/x.n>=.75?'good':x.right/x.n>=.6?'mid':'low'}" title="${h(fmtDate(x.at.slice(0,10)))}">${x.right}/${x.n}</span>`).join('')}</div>`}
function qzCard(){const c10=qzCounts(10);return `<section class="cisa-card cisa-section qz-card"><div class="cisa-row wrap"><div><div class="cisa-overline">Quick quiz · exam-weighted</div><h2>Practise in 10 or 25 questions</h2><p class="cisa-text cisa-muted" style="margin:4px 0 0">Questions are drawn from all three mock banks in the real exam proportions (D1 18% · D2 18% · D3 12% · D4 26% · D5 26%), favouring ones you haven't seen. Wrong answers go to your Mistakes notebook.</p></div><div class="cisa-actions">${button('qz-10','10 questions','primary')}${button('qz-25','25 questions')}</div></div>${qzHistory()}</section>`}
function quizUI(){const S=qzSession,total=S.queue.length;
 if(S.pos>=total){const p=pct(S.right,total);return `<section class="cisa-card cisa-section"><div class="cisa-overline">Quick quiz complete</div><h2>${S.right} of ${total} correct · ${p}%</h2>${progress(p)}<div class="qz-doms">${Object.keys(QZ_W).map(d=>{const v=S.dom[d]||[0,0];return v[1]?`<div><b>D${d}</b><span>${v[0]}/${v[1]}</span></div>`:''}).join('')}</div><p class="cisa-text">${p>=75?'Exam-ready pace. Keep mixing domains.':p>=60?'Close to the passing standard. Review the explanations for the ones you missed.':'Focus on the weaker domains above, then try another quiz.'} ${S.right<total?'Missed questions were added to your Mistakes notebook.':''}</p><div class="cisa-actions">${button('qz-end','Done','primary')}${button('qz-10','Another 10')}</div></section>`}
 const q=qIndex.get(S.queue[S.pos]),perm=S.orders[S.pos],picked=S.picked,ans=picked!==null;
 let after='';if(ans){const ok=picked===q.answer;after=`<div class="cisa-rationale"><b>${ok?'Correct.':'Not quite.'} Why the best answer is best</b>${h(q.explanation)}</div>${!ok&&q.choiceExplanations?.[picked]?`<div class="cisa-rationale"><b>Why your answer is not best</b>${h(q.choiceExplanations[picked].replace(/^Not the best answer\.\s*/,''))}</div>`:''}<div class="cisa-actions" style="margin-top:14px">${button('qz-next',S.pos+1<total?'Next question →':'See results','primary')}</div>`}
 return `<section class="cisa-card cisa-section"><div class="cisa-row wrap"><div><div class="cisa-overline">Quick quiz · question ${S.pos+1} of ${total}</div><div class="cisa-mini">Domain ${q.domain} · Topic ${h(q.topicId)} · ${S.right} correct so far</div></div>${button('qz-end','End quiz','sm')}</div>${progress(pct(S.pos+(ans?1:0),total))}<p class="cisa-text cisa-question">${h(q.question)}</p><div class="cisa-answers">${perm.map((o,pos)=>ans?`<div class="cisa-answer ${o===q.answer?'is-correct':''} ${o===picked&&o!==q.answer?'is-wrong':''}"><b>${'ABCD'[pos]}</b><div>${h(q.choices[o])}${o===q.answer?' <em>· Best answer</em>':''}${o===picked&&o!==q.answer?' <em>· Your answer</em>':''}</div></div>`:`<button type="button" class="cisa-answer" data-action="qz-pick" data-option="${o}"><b>${'ABCD'[pos]}</b><span>${h(q.choices[o])}</span></button>`).join('')}</div>${after}</section>`}

/* ---------- calendar (.ics) export ---------- */
function icsUI(){return `<form data-form="ics" id="cisaIcsForm" class="pl-sec"><p class="cisa-mini" style="margin:0 0 12px">Downloads a calendar file with one event per study day from today to your exam. Open it to add the sessions to Apple Calendar, Google Calendar or Outlook.</p><div class="cisa-fields" style="grid-template-columns:1fr 1fr"><label>Study start time<input type="time" name="time" value="${h(state.icsTime||'19:00')}" required></label><label>Reminder<select name="alarm">${[['0','None'],['10','10 minutes before'],['30','30 minutes before'],['60','1 hour before']].map(([v,l])=>`<option value="${v}" ${String(state.icsAlarm??'10')===v?'selected':''}>${l}</option>`).join('')}</select></label></div></form>`}
function buildIcs(time,alarm){const t=timeline(),now=dateStr(new Date()),p=getPlan(),[hh,mm]=time.split(':').map(Number),esc=x=>String(x).replace(/\\/g,'\\\\').replace(/;/g,'\;').replace(/,/g,'\\,').replace(/\n/g,'\\n');
 const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+/,'');const fmt=(ds,mins)=>{const d=new Date(ds+'T00:00:00');d.setHours(hh,mm+mins,0,0);const z=n=>String(n).padStart(2,'0');return `${d.getFullYear()}${z(d.getMonth()+1)}${z(d.getDate())}T${z(d.getHours())}${z(d.getMinutes())}00`};
 const out=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//JS Learning//CISA Study Plan//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH','X-WR-CALNAME:CISA study plan'];let n=0;
 for(const ds of t.days.filter(d=>d>=now)){const items=t.byday[ds]||[];if(!items.length)continue;const mins=items.reduce((a,x)=>a+(x.minutes||0),0)||60;const isExam=items.some(x=>!x.topic&&!x.mock);
  const title=isExam?'CISA exam (target date)':items.some(x=>x.mock)?'CISA mock exam '+items.find(x=>x.mock).mock:'CISA study · '+items.filter(x=>x.topic).map(x=>x.topic.id).join(', ');
  const desc=items.map(x=>x.topic?`${x.topic.id} ${titleOf(x.topic)} (${x.minutes} min)`:x.mock?`Practice mock examination ${x.mock}`:'Target CISA examination').join('\n');
  out.push('BEGIN:VEVENT',`UID:cisa-${ds}-${p.examDate}@jslearning`,`DTSTAMP:${stamp}`);
  if(isExam){out.push(`DTSTART;VALUE=DATE:${ds.replace(/-/g,'')}`)}else{out.push(`DTSTART:${fmt(ds,0)}`,`DTEND:${fmt(ds,mins)}`)}
  out.push(`SUMMARY:${esc(title)}`,`DESCRIPTION:${esc(desc)}`);if(+alarm&&!isExam)out.push('BEGIN:VALARM','ACTION:DISPLAY',`DESCRIPTION:${esc(title)}`,`TRIGGER:-PT${+alarm}M`,'END:VALARM');out.push('END:VEVENT');n++}
 out.push('END:VCALENDAR');return {text:out.join('\r\n')+'\r\n',n}}
function dlFile(name,text,type){const b=new Blob([text],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000)}

/* ---------- focus timer (logs to the Daily recorder when finished) ---------- */
const mmss=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`;
function focusLeft(){return focus.running?Math.max(0,Math.round((focus.endAt-Date.now())/1000)):focus.left}
function focusCard(){const left=focusLeft(),tot=focus.dur*60,frac=tot?1-left/tot:0,C=2*Math.PI*52;return `<section class="cisa-card cisa-section focus-card"><div class="focus-ring"><svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="52" class="fr-bg"/><circle cx="60" cy="60" r="52" class="fr-fg" id="cisaFocusArc" stroke-dasharray="${C.toFixed(1)}" stroke-dashoffset="${(C*(1-frac)).toFixed(1)}"/></svg><span id="cisaFocus" aria-live="off">${mmss(left)}</span></div><div class="focus-body"><div class="cisa-overline">Focus timer</div><h2>${focus.running?'Stay with it':'Start a focused session'}</h2><p class="cisa-mini" style="margin:2px 0 10px">When the timer finishes, the session is saved to your Daily recorder automatically.</p><div class="cisa-actions">${[25,50].map(m=>`<button type="button" class="cisa-btn sm ${focus.dur===m?'primary':''}" data-action="focus-len" data-min="${m}" ${focus.running?'disabled':''}>${m} min</button>`).join('')}<select data-action="focus-domain" aria-label="Domain" ${focus.running?'disabled':''}>${syllabus.domains.map(d=>`<option value="${d.id}" ${String(focus.domain)===String(d.id)?'selected':''}>D${d.id} · ${h(d.name)}</option>`).join('')}</select><select data-action="focus-topic" aria-label="Topic" ${focus.running?'disabled':''}><option value="">Any topic</option>${allTopics().filter(t=>String(t.domain)===String(focus.domain)).map(t=>`<option value="${h(t.id)}" ${focus.topic===t.id?'selected':''}>${h(t.id)} · ${h(titleOf(t))}</option>`).join('')}</select></div><div class="cisa-actions" style="margin-top:10px">${focus.running?button('focus-pause','Pause','primary'):button('focus-start',focus.left<focus.dur*60?'Resume':'Start','primary')}${button('focus-reset','Reset')}</div></div></section>`}
function focusTick(){const el=document.getElementById('cisaFocus');const left=focusLeft();if(el){el.textContent=mmss(left);const arc=document.getElementById('cisaFocusArc');if(arc){const C=2*Math.PI*52;arc.setAttribute('stroke-dashoffset',(C*(left/(focus.dur*60))).toFixed(1))}}
 if(focus.running&&left<=0){clearInterval(focusTimer);focusTimer=null;focus.running=false;focus.left=focus.dur*60;state.logs.push({id:'log'+Date.now(),date:dateStr(new Date()),domain:+focus.domain||1,topicId:focus.topic||'',minutes:focus.dur,questions:0,correct:0,confidence:3,notes:'Focus timer session'});state.logs=state.logs.slice(-200);persist();
  try{const AC=window.AudioContext||window.webkitAudioContext;const ac=new AC();[0,.25,.5].forEach(t=>{const o=ac.createOscillator(),g=ac.createGain();o.frequency.value=880;g.gain.setValueAtTime(.12,ac.currentTime+t);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+t+.2);o.connect(g).connect(ac.destination);o.start(ac.currentTime+t);o.stop(ac.currentTime+t+.22)})}catch(e){}
  try{if('Notification' in window&&Notification.permission==='granted')new Notification('Focus session complete',{body:focus.dur+' minutes saved to your CISA Daily recorder.'})}catch(e){}
  if(root&&document.body.contains(root)&&tab==='recorder')layout();else{const t=document.createElement('div');t.className='toast';t.textContent='Focus session complete · '+focus.dur+' min logged';document.body.appendChild(t);setTimeout(()=>t.remove(),3500)}}}

/* ---------- Dashboard "Today" summary (used by index.html) ---------- */
export async function todayInfo(read){if(!syllabus){[syllabus,templates.normal,templates.relaxed]=await Promise.all([fetchData('./data/syllabus.json'),fetchData('./data/normal-plan.json'),fetchData('./data/relaxed-plan.json')])}
 const saved=state;try{state=Object.assign(defaultState(),read()||{});ensureImported();const t=timeline(),now=dateStr(new Date());const items=(t.byday[now]||[]).map(x=>x.topic?{id:x.topic.id,title:titleOf(x.topic),minutes:x.minutes,done:!!state.complete[x.topic.id]}:{id:x.mock?'mock'+x.mock:'exam',title:x.mock?'Practice mock examination '+x.mock:'CISA exam (target)',minutes:x.minutes,done:false});
  const over=new Set();for(const ds of t.days.filter(d=>d<now))for(const x of t.byday[ds]||[])if(x.topic&&!state.complete[x.topic.id])over.add(x.topic.id);
  const next=items.length?null:(()=>{const d=t.days.find(d=>d>now&&(t.byday[d]||[]).length);return d?{date:d,count:t.byday[d].length}:null})();
  return {items,overdue:over.size,mistakesDue:mxDue().length,locked:locked(),mode:state.planMode,loggedToday:state.logs.filter(l=>l.date===now).reduce((a,l)=>a+Number(l.minutes||0),0),next}}finally{state=saved}}

function modalsUI(){if(!modals.length)return '';const p=getPlan();const def={plan:{title:h(p.title),sub:`${h(fmtDate(p.start))} → ${h(fmtDate(p.examDate))} · ${state.planMode==='normal'?'Normal':'Relaxed'} plan`,body:planFullUI,foot:locked()?`${button('plan-ics','Add to calendar')}${button('modal-close','Done','primary')}`:`${button('plan-ics','Add to calendar')}${button('modal-close','Done')}${button('plan-config','Set up plan','primary')}`},config:{title:'Set up your plan',sub:'One-time setup · dates, weekly hours and topics',body:planConfigUI,foot:`${button('modal-close','Cancel')}<button type="submit" form="cisaPlanForm" class="cisa-btn primary">Save &amp; lock plan</button>`},ics:{title:'Add to calendar',sub:'Your study plan as calendar events',body:icsUI,foot:`${button('modal-close','Cancel')}<button type="submit" form="cisaIcsForm" class="cisa-btn primary">Download .ics</button>`},admin:{title:'Admin unlock',sub:'The admin signs in here to unlock this plan',body:adminUI,foot:`${button('modal-close','Cancel')}<button type="submit" form="cisaAdminForm" class="cisa-btn primary" ${adminBusy?'disabled':''}>${adminBusy?'Checking…':'Unlock plan'}</button>`}};
 return modals.map((m,i)=>{const d=def[m];return `<div class="ap-modal ${i<modals.length-1?'is-under':''} ${modalAnim===m?'anim':''}" data-modal="${m}" role="dialog" aria-modal="true" aria-label="${d.title}"><div class="ap-backdrop" data-action="modal-close"></div><div class="ap-sheet ap-${m}"><header class="ap-head"><button type="button" class="ap-x" data-action="modal-close" aria-label="Close">×</button><div><h3>${d.title}</h3><p>${d.sub}</p></div></header><div class="ap-body" data-scroll="${m}">${d.body()}</div><footer class="ap-foot">${d.foot}</footer></div></div>`}).join('')}
function layout(){if(!root)return; if(tab==='exam'){root.innerHTML='<div class="cisa-hub">'+examUI()+'</div>';attach();return}if(tab==='result'){root.innerHTML='<div class="cisa-hub">'+resultUI(examBank?.id||1)+'</div>';attach();return}let content={overview,planner,syllabus:syllabusUI,recorder,revision:revisionsUI,mocks:mocksUI,mistakes:mistakesUI,analytics:analyticsUI,notes:notesUI};const keep={};root.querySelectorAll('.ap-body[data-scroll]').forEach(b=>keep[b.dataset.scroll]=b.scrollTop);root.innerHTML='<div class="cisa-hub">'+header()+(content[tab]||overview)()+modalsUI()+'</div>';root.querySelectorAll('.ap-body[data-scroll]').forEach(b=>{if(keep[b.dataset.scroll])b.scrollTop=keep[b.dataset.scroll]});modalAnim=null;document.documentElement.classList.toggle('ap-lock',modals.length>0);attach();}
function attach(){if(timer){clearInterval(timer);timer=null}if(tab==='exam'){timer=setInterval(()=>{const draft=state.drafts[examBank?.id];if(!draft)return;if(Date.now()>=draft.endAt){clearInterval(timer);finishMock(examBank.id,true);tab='result';reviewQuestion=0;layout();return}const el=$('[data-time]');if(el)el.textContent=timeLeft(draft.endAt)},1000)}if(tab==='recorder'&&stopwatchStart)beginWatch()}
function navigate(t){if(timer){clearInterval(timer);timer=null}if(t!=='mistakes')mxSession=null;if(t!=='mocks')qzSession=null;tab=t;editTopic=null;modals=[];focusedTopic=null;layout();window.scrollTo({top:0,behavior:'instant'})}
function download(filename,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(rows){return rows.map(row=>row.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n')}
function info(msg){alert(msg)}
function migrateDraft(id){const d=state.drafts[id],b=bankCache[id];if(!d||!b||(d.v||1)>=(b.version||1))return;for(const qid of b.rewrittenInV2||[])delete d.answers[qid];d.v=b.version;persist()}
async function loadBank(id,setCurrent=true){bankCache[id]??=await fetchData(`./mock-exams/mock-0${id}.json`);migrateDraft(id);if(setCurrent)examBank=bankCache[id];return bankCache[id]}
function finishMock(id,auto=false){const draft=state.drafts[id];if(!draft||!examBank||examBank.id!==id)return;const data=examBank.questions,stats={},topicStats={},wrong=[];let correct=0;for(const q of data){const hit=draft.answers[q.id]===q.answer;if(hit)correct++;else wrong.push({id:q.id,topicId:q.topicId});stats[q.domain]??={total:0,correct:0};stats[q.domain].total++;if(hit)stats[q.domain].correct++;topicStats[q.topicId]??={total:0,correct:0};topicStats[q.topicId].total++;if(hit)topicStats[q.topicId].correct++;}const attempt=(state.mockAttempts[id]||0)+1;state.mockAttempts[id]=attempt;const r={id:'r'+Date.now(),mockId:id,attempt,date:new Date().toISOString(),correct,total:data.length,unanswered:data.length-Object.keys(draft.answers).length,elapsed:Math.min(Date.now()-draft.startedAt,240*60000),stats,topicStats,wrong,answers:draft.answers,order:draft.order||'',v:draft.v||1,auto};for(const w of wrong)if(draft.answers[w.id]!==undefined)mxAddWrong(w.id,id);state.results.push(r);state.results=trimResults(state.results);delete state.drafts[id];state.activeMock=null;persist()}
function updateDraft(){persist();layout()}
function beginWatch(){if(stopWatch)clearInterval(stopWatch);stopWatch=setInterval(()=>{const el=$('#cisa-study-timer');if(el){const s=Math.floor((Date.now()-stopwatchStart+stopwatchElapsed)/1000);el.textContent=pad(Math.floor(s/60))+':'+pad(s%60)}},1000)}
function closeModal(){if(!modals.length)return;const top=root.querySelector('.ap-modal:last-of-type');const done=()=>{const m=modals.pop();if(m==='config')editTopic=null;layout()};if(top&&!matchMedia('(prefers-reduced-motion: reduce)').matches){top.classList.add('closing');setTimeout(done,190)}else done()}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modals.length&&root&&document.body.contains(root)){e.preventDefault();closeModal()}});
function action(ev){const btn=ev.target.closest('[data-action]');if(!btn||!root.contains(btn))return;const a=btn.dataset.action,id=btn.dataset.topic,mode=btn.dataset.mock&&Number(btn.dataset.mock);if(btn.type==='checkbox')return;let previousScroll=window.scrollY;
 if(a==='qz-10'||a==='qz-25'){loadAllBanks().then(()=>qzBegin(a==='qz-10'?10:25)).catch(e=>fail(e.message));return}
 if(a==='qz-pick'){if(!qzSession||qzSession.picked!==null)return;const id=qzSession.queue[qzSession.pos],q=qIndex.get(id),o=Number(btn.dataset.option),ok=o===q.answer;qzSession.picked=o;const dm=qzSession.dom[q.domain]||(qzSession.dom[q.domain]=[0,0]);dm[1]++;if(ok){qzSession.right++;dm[0]++}else mxAddWrong(id,q.mockId);state.qzSeen=[...(state.qzSeen||[]).filter(x=>x!==id),id].slice(-600);persist();layout();return}
 if(a==='qz-next'){if(!qzSession)return;qzSession.pos++;qzSession.picked=null;if(qzSession.pos>=qzSession.queue.length){state.quizzes=[...(state.quizzes||[]),{at:new Date().toISOString(),n:qzSession.queue.length,right:qzSession.right,dom:qzSession.dom}].slice(-100);persist()}layout();window.scrollTo({top:0,behavior:'instant'});return}
 if(a==='qz-end'){if(qzSession&&qzSession.pos>0&&qzSession.pos<qzSession.queue.length){const n=qzSession.pos;state.quizzes=[...(state.quizzes||[]),{at:new Date().toISOString(),n,right:qzSession.right,dom:qzSession.dom,partial:true}].slice(-100);persist()}qzSession=null;layout();return}
 if(a==='plan-ics'){if(!modals.includes('ics')){modals=[...modals,'ics'];modalAnim='ics'}layout();return}
 if(a==='focus-len'){if(focus.running)return;focus.dur=+btn.dataset.min;focus.left=focus.dur*60;layout();return}
 if(a==='focus-start'){focus.running=true;focus.endAt=Date.now()+focus.left*1000;try{if('Notification' in window&&Notification.permission==='default')Notification.requestPermission()}catch(e){}clearInterval(focusTimer);focusTimer=setInterval(focusTick,1000);layout();return}
 if(a==='focus-pause'){focus.left=focusLeft();focus.running=false;clearInterval(focusTimer);focusTimer=null;layout();return}
 if(a==='focus-reset'){focus.running=false;clearInterval(focusTimer);focusTimer=null;focus.left=focus.dur*60;layout();return}
 if(locked()&&LOCKED_ACTIONS.includes(a)){info('Your study plan is locked. Ask the admin to unlock it.');return}
 if(a==='admin-auth'){adminErr='';if(!modals.includes('admin')){modals=[...modals,'admin'];modalAnim='admin'}layout();setTimeout(()=>root.querySelector('#cisaAdminForm input')?.focus(),60);return}
 if(a==='admin-unlock'){if(!ctx.isAdmin)return;if(confirm('Unlock this study plan so it can be set up again?')){state.planLock={locked:false,unlockedAt:new Date().toISOString()};persist();layout()}return}
 if(a==='nav'){navigate(btn.dataset.target);return}
 if(a==='mx-start'||a==='mx-start-all'||a==='mx-one'){loadAllBanks().then(()=>{let ids;if(a==='mx-one')ids=[btn.dataset.id];else{const pool=(a==='mx-start'?mxDue():mxActive()).filter(c=>qIndex.has(c.id)).sort((x,y)=>x.d.localeCompare(y.d)||(y.w||1)-(x.w||1));ids=pool.slice(0,a==='mx-start'?50:30).map(c=>c.id)}if(ids.length)mxBegin(ids)}).catch(e=>fail(e.message));return}
 if(a==='mx-pick'){if(!mxSession||mxSession.picked!==null)return;const id=mxSession.queue[mxSession.pos],q=qIndex.get(id),o=Number(btn.dataset.option),ok=o===q.answer;mxSession.picked=o;if(ok)mxSession.right++;mxRecord(id,ok);persist();layout();return}
 if(a==='mx-next'){if(!mxSession)return;mxSession.pos++;mxSession.picked=null;layout();window.scrollTo({top:0,behavior:'instant'});return}
 if(a==='mx-end'){mxSession=null;layout();return}
 if(a==='mx-remove'){if(confirm('Remove this question from your Mistakes notebook?')){delete state.mistakes[btn.dataset.id];persist();layout()}return}

 if(a==='mode-normal'||a==='mode-relaxed'){state.planMode=a.endsWith('normal')?'normal':'relaxed';weekIndex=0;persist();layout();return}
 if(a==='prev-week'||a==='next-week'||a==='today-week'){weekIndex=a==='prev-week'?weekIndex-1:a==='next-week'?weekIndex+1:clamp(Math.floor(dayDiff(getPlan().start,dateStr(new Date()))/7),0,99);layout();return}
 if(a==='reset-plan'){if(confirm('Restore the selected plan’s default dates and study hours? Completed work and notes will remain.')){state.plans[state.planMode]=structuredClone(templates[state.planMode]);persist();layout()}return}
 if(a==='plan-open'){modals=['plan'];modalAnim='plan';layout();return}
 if(a==='plan-config'){if(!modals.includes('config')){modals=[...modals.filter(m=>m!=='config'),'config'];modalAnim='config'}layout();return}
 if(a==='modal-close'){closeModal();return}
 if(a==='edit-topic'||a==='new-topic'){editTopic=a==='new-topic'?'new':id;if(tab!=='planner'){tab='planner'}if(!modals.includes('config')){modals=[...modals,'config'];modalAnim='config'}layout();requestAnimationFrame(()=>{const f=root.querySelector('.ap-config form[data-form="topic"]');if(f)f.scrollIntoView({block:'start',behavior:'smooth'})});return}
 if(a==='cancel-edit'){editTopic=null;layout();return}
 if(a==='open-topic'){focusedTopic=id;tab=tab==='revision'?'revision':'syllabus';layout();$('#cisa-topic-detail')?.scrollIntoView({block:'start'});return}
 if(a==='close-topic'){focusedTopic=null;layout();return}
 if(a==='complete-toggle'){state.complete[id]=!state.complete[id];persist();layout();return}
 if(a==='move-up'||a==='move-down'){const arr=allTopics().map(x=>x.id),i=arr.indexOf(id),j=i+(a==='move-up'?-1:1);if(j>=0&&j<arr.length){[arr[i],arr[j]]=[arr[j],arr[i]];state.order=arr;persist();layout()}return}
 if(a==='delete-custom'){if(confirm('Delete this custom task?')){state.customTasks=state.customTasks.filter(x=>x.id!==id);state.order=state.order.filter(x=>x!==id);state.hidden=state.hidden.filter(x=>x!==id);delete state.complete[id];delete state.topicEdits[id];persist();layout()}return}
 if(a==='delete-log'){if(confirm('Delete this study record?')){state.logs=state.logs.filter(x=>x.id!==btn.dataset.id);persist();layout()}return}
 if(a==='schedule-review'||a==='review-done'){const count=state.revisionCounts[id]||0;const intervals=[1,3,7,14];if(a==='review-done')state.revisionCounts[id]=count+1;const date=dateAdd(dateStr(new Date()),a==='schedule-review'?1:intervals[Math.min(count,3)]);state.revisions[id]=date;persist();layout();return}
 if(a==='remove-review'){delete state.revisions[id];persist();layout();return}
 if(a==='catchup'){let ds=dateStr(new Date()),p=getPlan();if(ds<p.start)ds=p.start;for(let n=0;n<365;n++,ds=dateAdd(ds,1)){if((p.weeklyMinutes||[])[dayIdx(ds)]>0)break}if(ds>p.examDate){info('No remaining study day before your exam target. Edit the plan dates or weekly hours.');return}state.topicEdits[id]={...(state.topicEdits[id]||{}),date:ds};persist();layout();return}
 if(a==='timer-start'){if(!stopwatchStart){stopwatchStart=Date.now()}beginWatch();return}
 if(a==='timer-stop'){if(stopwatchStart){stopwatchElapsed+=Date.now()-stopwatchStart;stopwatchStart=null}clearInterval(stopWatch);const el=$('#cisa-duration');if(el)el.value=Math.max(1,Math.ceil(stopwatchElapsed/60000));return}
 if(a==='export-json'){download('cisa-backup-'+dateStr(new Date())+'.json',JSON.stringify({kind:'jslearning-cisa-v1',data:state},null,2),'application/json');return}
 if(a==='export-csv'){download('cisa-study-records.csv',csv([['Date','Domain','Topic','Minutes','Questions','Correct','Confidence','Notes'],...state.logs.map(x=>[x.date,x.domain,x.topicId,x.minutes,x.questions,x.correct,x.confidence,x.notes])]),'text/csv');return}
 if(a==='export-plan'){
   const t=timeline();
   const rows=[['Date','Task','Domain','Minutes','Complete']];
   for(const d of t.days){for(const x of t.byday[d]){
     rows.push([d,x.topic?titleOf(x.topic):x.mock?'Mock '+x.mock:'Target CISA exam',x.topic?x.topic.domain:'',x.minutes,x.topic?!!state.complete[x.topic.id]:'']);
   }}
   download('cisa-planner-'+state.planMode+'.csv',csv(rows),'text/csv');return;
 }
 if(a==='note-open'){focusedTopic=id;tab='notes';layout();return}
 if(a==='mock-start'){if(!state.drafts[mode]){if(!confirm('Start a 150-question, four-hour practice exam? Your timer will continue if you navigate away.'))return;state.drafts[mode]={startedAt:Date.now(),endAt:Date.now()+240*60000,answers:{},flags:[],order:makeOrder(150),v:2};persist()}tab='exam';examPage=0;loadBank(mode).then(()=>layout()).catch(e=>fail(e.message));layout();return}
 if(a==='mock-result'){tab='result';reviewQuestion=0;loadBank(mode).then(()=>layout()).catch(e=>fail(e.message));layout();return}
 if(a==='choose'){const d=state.drafts[examBank.id],q=examBank.questions[examPage];d.answers[q.id]=Number(btn.dataset.option);updateDraft();return}
 if(a==='flag'){const d=state.drafts[examBank.id],q=examBank.questions[examPage];d.flags.includes(q.id)?d.flags=d.flags.filter(x=>x!==q.id):d.flags.push(q.id);updateDraft();return}
 if(a==='mock-go'||a==='mock-prev'||a==='mock-next'){examPage=a==='mock-go'?Number(btn.dataset.q):clamp(examPage+(a==='mock-prev'?-1:1),0,149);layout();window.scrollTo({top:0,behavior:'instant'});return}
 if(a==='mock-submit'){const d=state.drafts[examBank.id];const remaining=150-Object.keys(d.answers).length;if(confirm(`Submit this mock examination now? ${remaining} questions are unanswered. You will then see the score and explanations.`)){finishMock(examBank.id);tab='result';reviewQuestion=0;layout()}return}
 if(a==='result-prev'||a==='result-next'){reviewQuestion=clamp(reviewQuestion+(a==='result-prev'?-1:1),0,149);layout();return}
 if(a==='mock-reset'){if(confirm('Start a fresh attempt? Previous submitted results are preserved.')){delete state.drafts[mode];persist();tab='mocks';layout()}return}
 }
function changes(e){const el=e.target;if(!el.dataset.action)return;const a=el.dataset.action,id=el.dataset.topic;if(a==='note-switch'){focusedTopic=el.value;layout();return}if(a==='mx-filter'){mxFilter=el.value;layout();return}if(a==='focus-domain'){focus.domain=el.value;focus.topic='';layout();return}if(a==='focus-topic'){focus.topic=el.value;return}if(a==='complete'){state.complete[id]=el.checked;persist();layout();return}if(a==='include'&&locked()){el.checked=!el.checked;info('Your study plan is locked. Ask the admin to unlock it.');return}if(a==='include'){state.hidden=el.checked?state.hidden.filter(x=>x!==id):[...new Set([...state.hidden,id])];persist();layout();return}if(a==='registered'||a==='booked'){state.registration[a]=el.checked;persist();return}}
async function submit(e){const f=e.target;if(!f.dataset.form)return;e.preventDefault();const v=Object.fromEntries(new FormData(f));const n=f.dataset.form;
 if((n==='plan'||n==='topic')&&locked()){info('Your study plan is locked. Ask the admin to unlock it.');return}
 if(n==='ics'){const r=buildIcs(String(v.time||'19:00'),String(v.alarm||'0'));state.icsTime=v.time;state.icsAlarm=v.alarm;persist();if(!r.n){info('There are no study days left in your plan to export.');return}dlFile("cisa-study-plan.ics",r.text,"text/calendar");modals=modals.filter(m=>m!=='ics');layout();return}
 if(n==='admin'){if(adminBusy)return;adminEmail=String(v.email||'').trim();if(!ctx.verifyAdmin){adminErr='Admin check is not available.';layout();return}adminBusy=true;adminErr='';layout();let r=null;try{r=await ctx.verifyAdmin(String(v.email||'').trim(),String(v.password||''))}catch(err){r=null}adminBusy=false;const ok=r===true||!!(r&&r.ok);if(!ok){adminErr=(r&&r.err)||'Those are not the admin’s sign-in details.';layout();return}state.planLock={locked:false,unlockedAt:new Date().toISOString()};persist();adminErr='';adminEmail='';modals=modals.filter(m=>m!=='admin');layout();info('Plan unlocked. You can now set it up again.');return}
 if(n==='plan'){if(v.start>=v.examDate){info('The target exam date must be later than the start date.');return}if(v.examDate>v.deadline){info('Target exam date must be on or before your deadline.');return}if(dayDiff(v.start,v.examDate)>729){info('Use a study period shorter than two years.');return}const p=getPlan();Object.assign(p,{start:v.start,examDate:v.examDate,deadline:v.deadline,title:v.title.slice(0,90),reviewDays:clamp(+v.reviewDays||10,3,40),weeklyMinutes:WD.map((_,i)=>clamp(+v['wd'+i]||0,0,600))});if(p.weeklyMinutes.every(x=>!x)){info('Set study time on at least one day per week.');return}if(!confirm('Save and lock this '+(state.planMode==='normal'?'Normal':'Relaxed')+' plan?\n\nAfter locking, you cannot change the plan type, dates, hours or topics. Only the admin can unlock it.'))return;state.plans[state.planMode]=p;state.planLock={locked:true,mode:state.planMode,at:new Date().toISOString()};weekIndex=0;persist();if(modals[modals.length-1]==='config'){closeModal();return}layout();return}
 if(n==='topic'){const id=v.id;if(!v.title.trim()){info('Enter a topic title.');return}if(v.date&&(v.date<getPlan().start||v.date>getPlan().examDate)){info('Preferred date must be between the plan start and target exam date.');return}if(id==='new'){let newId='P'+Date.now().toString(36);state.customTasks.push({id:newId,title:v.title.trim(),domain:clamp(+v.domain,1,5),section:'Personal study',minutes:clamp(+v.minutes,15,300),custom:true});state.topicEdits[newId]={date:v.date||'',notes:v.notes||'',title:v.title.trim(),minutes:clamp(+v.minutes,15,300)};}else{state.topicEdits[id]={title:v.title.trim(),minutes:clamp(+v.minutes,15,300),date:v.date||'',notes:v.notes||''};if(state.customTasks.some(x=>x.id===id)){state.customTasks.find(x=>x.id===id).domain=clamp(+v.domain,1,5)}}editTopic=null;persist();layout();return}
 if(n==='log'){if(+v.correct>+v.questions){info('Correct answers cannot exceed questions attempted.');return}if(!v.date||!+v.minutes){info('Date and study duration are required.');return}state.logs.push({id:'log'+Date.now(),date:v.date,domain:+v.domain,topicId:v.topicId||'',minutes:clamp(+v.minutes,1,1440),questions:clamp(+v.questions||0,0,1000),correct:clamp(+v.correct||0,0,1000),confidence:+v.confidence,notes:(v.notes||'').slice(0,1000)});state.logs=state.logs.slice(-200);stopwatchStart=null;stopwatchElapsed=0;clearInterval(stopWatch);persist();layout();return}
 if(n==='notes'){state.notes[v.id]=(v.note||'').slice(0,2500);focusedTopic=v.id;persist();layout();return}
 if(n==='import'){const file=f.elements.backup.files?.[0];if(!file)return;if(file.size>2_000_000){info('Backup is too large (maximum 2 MB).');return}try{const obj=JSON.parse(await file.text());if(obj.kind!=='jslearning-cisa-v1'||!obj.data||typeof obj.data!=='object')throw Error('Not a JS Learning CISA backup');if(!confirm('Replace this account’s existing CISA progress with the imported backup?'))return;state=Object.assign(defaultState(),obj.data);ensureImported();persist();layout()}catch(err){info('Unable to import: '+err.message)}return}
}
function ensureImported(){state.plans=state.plans||{};state.complete=state.complete||{};state.topicEdits=state.topicEdits||{};state.customTasks=Array.isArray(state.customTasks)?state.customTasks:[];state.logs=Array.isArray(state.logs)?state.logs:[];state.results=Array.isArray(state.results)?state.results:[];state.order=Array.isArray(state.order)?state.order:[];state.hidden=Array.isArray(state.hidden)?state.hidden:[];state.notes=state.notes||{};state.revisions=state.revisions||{};state.drafts=state.drafts||{};state.registration=state.registration||{registered:false,booked:false};state.revisionCounts=state.revisionCounts||{};state.mistakes=(state.mistakes&&typeof state.mistakes==='object')?state.mistakes:{};state.mockAttempts=state.mockAttempts||{};normaliseAttempts();if(!state.plans.normal)state.plans.normal=structuredClone(templates.normal);if(!state.plans.relaxed)state.plans.relaxed=structuredClone(templates.relaxed);if(!['normal','relaxed'].includes(state.planMode))state.planMode='normal';if(state.planLock&&state.planLock.locked&&['normal','relaxed'].includes(state.planLock.mode))state.planMode=state.planLock.mode}
function fail(message){if(root)root.innerHTML=`<div class="cisa-hub"><div class="cisa-error"><b>Unable to load the CISA module.</b><p>${h(message)}</p><p>Upload <code>cisa/</code> as a folder alongside <code>index.html</code>, including its JS, CSS and JSON files.</p></div></div>`}
export async function mount({root:target,read,write,isAdmin=false,verifyAdmin=null,tab:startTab=null,topic:startTopic=null}){ctx={isAdmin:!!isAdmin,verifyAdmin};root=target;if(startTopic)focusedTopic=startTopic;if(startTab&&['overview','planner','syllabus','recorder','revision','mocks','mistakes','analytics','notes'].includes(startTab)){tab=startTab;mxSession=null;qzSession=null;modals=[]}readParent=read;writeParent=write;root.innerHTML='<div class="cisa-hub"><div class="cisa-card">Loading CISA Academy, planner and syllabus…</div></div>';try{if(!syllabus){[syllabus,templates.normal,templates.relaxed]=await Promise.all([fetchData('./data/syllabus.json'),fetchData('./data/normal-plan.json'),fetchData('./data/relaxed-plan.json')])}ensureState();weekIndex=clamp(Math.floor(dayDiff(getPlan().start,dateStr(new Date()))/7),0,99);root.onclick=action;root.onchange=changes;root.onsubmit=submit;layout()}catch(e){console.error(e);fail(e.message)}}
